definition.script:
pipeline {
    agent any

    environment {
        IMAGE_TAG = "shieldops-scan-${env.COMMIT_SHA?.take(7) ?: 'latest'}"
        TRIVY_SEVERITY = "CRITICAL,HIGH"
    }

    stages {
        stage('Checkout') {
            steps {
                sh '''
                    rm -rf workspace-repo
                    git clone ${REPO_URL} workspace-repo
                    cd workspace-repo
                    if [ -n "${COMMIT_SHA}" ]; then
                        git checkout ${COMMIT_SHA} || true
                    fi
                '''
            }
        }

        stage('Trivy Scan') {
            steps {
                script {
                    def exitCode = sh(returnStatus: true, script: '''
                        if docker image inspect ${IMAGE_TAG} > /dev/null 2>&1; then
                            trivy image --severity ${TRIVY_SEVERITY} --exit-code 1 --no-progress --format table ${IMAGE_TAG} | tee trivy-report.txt
                        else
                            trivy fs --severity ${TRIVY_SEVERITY} --exit-code 1 --no-progress --format table workspace-repo/ | tee trivy-report.txt
                        fi
                    ''')
                    env.SCAN_STATUS = (exitCode == 0) ? "success" : "failure"
                }
            }
        }

        stage('Cleanup') {
            steps {
                sh 'docker rmi ${IMAGE_TAG} || true; rm -rf workspace-repo'
            }
        }
    }

    post {
        always {
            archiveArtifacts artifacts: 'trivy-report.txt', allowEmptyArchive: true
        }
    }
}
